param([string]$SecretPath=(Join-Path $env:LOCALAPPDATA 'AGM\secrets\live-provider-pilot.dpapi'),[ValidateSet('TomTom','HERE','TollGuru')][string[]]$Provider=@('TomTom','HERE','TollGuru'))
$ErrorActionPreference='Stop';if(!(Test-Path -LiteralPath $SecretPath)){throw 'LIVE_PROVIDER_DPAPI_BUNDLE_MISSING'}
$encrypted=[IO.File]::ReadAllText($SecretPath,[Text.Encoding]::UTF8);$secure=ConvertTo-SecureString $encrypted;$ptr=[Runtime.InteropServices.Marshal]::SecureStringToBSTR($secure)
try{$raw=[Runtime.InteropServices.Marshal]::PtrToStringBSTR($ptr);$bundle=$raw|ConvertFrom-Json;$allStatuses=@{TomTom=if($bundle.TOMTOM_API_KEY-match'^[A-Za-z0-9]+$'){'CONFIGURED'}else{'MISSING'};HERE=if($bundle.HERE_API_KEY.Length-ge 16){'CONFIGURED'}else{'MISSING'};TollGuru=if($bundle.TOLLGURU_API_KEY.Length-ge 16){'CONFIGURED'}else{'MISSING'}};$statuses=@{};foreach($item in $Provider){$statuses[$item]=$allStatuses[$item]};if($statuses.Values-contains'MISSING'){throw 'LIVE_PROVIDER_DPAPI_BUNDLE_INCOMPLETE'};[pscustomobject]@{Status='CUSTODY_VALIDATED';Providers=$statuses;SecretDisplayed=$false}|ConvertTo-Json -Compress}finally{[Runtime.InteropServices.Marshal]::ZeroFreeBSTR($ptr);$raw=$null;$bundle=$null;$secure=$null;$encrypted=$null}
